contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address callee, bytes memory data) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBefore = address(this).balance;
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(address(this).balance == balBefore);
    }
    receive() external payable {}
}

